<?php
// Local demonstration data. Existing records are preserved; the marker prevents duplicate seeding.
$db = new PDO('sqlite:' . __DIR__ . '/../database/prototype.sqlite', null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$db->exec('PRAGMA foreign_keys=ON');
$db->exec("CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY, record_id INTEGER NOT NULL REFERENCES records(id), type TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS demo_seed (name TEXT PRIMARY KEY)");
if ($db->query("SELECT COUNT(*) FROM demo_seed WHERE name='demo-v1'")->fetchColumn()) { echo "Demo data already added.\n"; exit; }
$assetNames=['Laptop','Monitor','Desktop PC','Printer','Network switch','Wireless access point','Keyboard','Mouse','UPS','Projector','Server','IP phone','Webcam','Docking station','Scanner'];
$staff=['Alex Santos','Jamie Cruz','Morgan Reyes','Sam Garcia','Taylor Ramos','Jordan Flores'];
$sites=['Marisol','San Fernando'];
$departments=['IT','Operations','Finance','Human Resources','Admin'];
$statuses=['In use','In use','In use','In storage','Under repair','Retired'];
$insert=$db->prepare('INSERT INTO records(kind,data) VALUES(?,?)');$event=$db->prepare('INSERT INTO events(record_id,type,detail,created_at) VALUES(?,?,?,?)');
$db->beginTransaction();
try {
 for($i=1;$i<=30;$i++) { $name=$assetNames[($i-1)%count($assetNames)];$status=$statuses[($i-1)%count($statuses)];$d=['asset_id'=>sprintf('DEMO-A%03d',$i),'serial'=>sprintf('DEMO-SN-%05d',$i),'name'=>$name,'category'=>in_array($name,['Laptop','Desktop PC','Server'])?'Computer':'Equipment','brand'=>['Dell','HP','Lenovo','Logitech','APC'][($i-1)%5],'model'=>'Demo model '.(100+$i),'specifications'=>$name==='Laptop'?'16 GB RAM, 512 GB SSD':'Sample specifications','employee'=>$status==='In use'?$staff[($i-1)%6]:'','department'=>$departments[($i-1)%5],'site'=>$sites[($i-1)%2],'room'=>'Room '.(101+$i%8),'status'=>$status,'condition'=>$status==='Under repair'?'Needs repair':'Good','purchase_cost'=>(string)(3500+$i*1250),'supplier'=>'Demo supplier','invoice'=>'DEMO-PO-'.sprintf('%04d',$i),'warranty'=>date('Y-m-d',strtotime(($i-10).' months')),'notes'=>'DEMO DATA — fictional sample record.'];$insert->execute(['assets',json_encode($d)]);$id=$db->lastInsertId();$event->execute([$id,'Record','Demo record created.',date('Y-m-d H:i:s',strtotime('-10 months'))]);if($i%4!==0)$event->execute([$id,'Audit','Demo physical audit recorded.',date('Y-m-d H:i:s',strtotime('-'.($i%9+1).' months'))]); }
 $items=['Copy paper','Black toner','Blue pens','USB-C cables','Ethernet cable','AA batteries','Shipping labels','Cleaning wipes','HDMI cables','Notebooks','Staples','Printer ink'];
 for($i=1;$i<=24;$i++){ $name=$items[($i-1)%12];$d=['sku'=>sprintf('DEMO-S%03d',(($i-1)%12)+1),'name'=>$name,'category'=>'Office supplies','location'=>$sites[(int)(($i-1)/12)],'quantity'=>(string)(($i*7)%60),'reorder'=>'12','supplier'=>'Demo supplier','unit_cost'=>(string)(40+$i*8),'notes'=>'DEMO DATA — fictional sample record.'];$insert->execute(['supplies',json_encode($d)]);$id=$db->lastInsertId();$event->execute([$id,'Record','Demo opening stock: '.$d['quantity'],date('Y-m-d H:i:s',strtotime('-2 months'))]); }
 $products=['Microsoft 365','Adobe Creative Cloud','Zoom Workplace','Endpoint security','Cloud backup','Project management','Password manager','Design software','VPN service','Domain registration','Cloud storage','Help desk','Analytics platform','Email security','Video conferencing'];
 for($i=1;$i<=15;$i++){ $d=['name'=>$products[$i-1].' (demo)','provider'=>['Microsoft','Adobe','Zoom','Example Software','Example Cloud'][($i-1)%5],'seats'=>(string)(20+$i*5),'assigned'=>(string)(10+$i*3),'assignments'=>'Demo assignments; no real employees.','cost'=>(string)(1000+$i*375),'frequency'=>$i%2?'Annual':'Monthly','renewal'=>date('Y-m-d',strtotime(($i-4).' months')),'expiry'=>date('Y-m-d',strtotime(($i-3).' months')),'documents'=>'Demo reference only','notes'=>'DEMO DATA — fictional sample record.'];$insert->execute(['licenses',json_encode($d)]);$event->execute([$db->lastInsertId(),'Record','Demo subscription created.',date('Y-m-d H:i:s',strtotime('-3 months'))]); }
 $db->exec("INSERT INTO demo_seed(name) VALUES('demo-v1')");$db->commit();echo "Added 30 assets, 24 supply location records and 15 subscriptions.\n";
} catch(Throwable $e){$db->rollBack();throw $e;}
